// Authored learning opportunities. The builder attaches the unchanged public baseline.
// Target levels describe task demands; they never certify personal attainment.
const L = (de, en) => ({ de, en });
const O = (criterionId, targetLevel, contextIds, text, task, evidence, successCriteria) => ({ criterionId, targetLevel, contextIds: contextIds.split(' '), text, task, evidence, successCriteria });
const no = 'without-ai', both = 'without-ai with-ai', about = 'without-ai about-ai';
const link = (moduleId, de, en) => ({ moduleId, reason: L(de, en) });
function M(id, knowledgeAnchors, futureSummary, objectives, aiRole, independentEvidence, assessmentProposal, workloadIntegration, openDecisions, prior = [], next = [], topicRequired = false) {
  return { id, proposal: { status: 'design-proposal', topicRequired, individualisationRequired: topicRequired,
    knowledgeAnchors, futureSummary, objectives: objectives.map((o, i) => ({ id: `${id}:o${i + 1}`, ...o })),
    activitySequence: L(objectives.map((o, i) => `${i + 1}. ${o.task.de}`).join('\n'), objectives.map((o, i) => `${i + 1}. ${o.task.en}`).join('\n')),
    aiRole, independentEvidence, assessmentProposal, workloadIntegration, openDecisions, spiralLinks: { prior, next } } };
}
